import {buildEventBundle,eventChronology,sortedEventChronology,eventBundleHTML} from './event-bundle-core.mjs';
export function mountEventBundle({document,window,clock=Date.now}){
  const get=id=>document.getElementById(id),el=(tag,text)=>{const n=document.createElement(tag);if(text!==undefined)n.textContent=text;return n;};let refs=[],bundle=null,generation=0,busy=false;
  const context=()=>{const event=window.WeatherEvents?.context?.()||{};return {story:event.story||null,asof:event.asof??null,panels:{reports:window.WeatherEventReports?.context?.()?.report||null,station:window.WeatherEventObservations?.context?.()?.report||null,gauge:window.WeatherEventGauges?.context?.()?.report||null}};};
  function controls(){get('event-bundle-prepare').disabled=busy||!context().story;get('event-bundle-json').disabled=busy||!bundle;get('event-bundle-html').disabled=busy||!bundle;get('event-bundle-basis').disabled=!bundle;}
  function refresh(){const c=context(),next=[c.story,c.asof,...Object.values(c.panels)];if(next.length===refs.length&&next.every((v,i)=>v===refs[i]))return;refs=next;generation++;busy=false;bundle=null;get('event-bundle-rows').replaceChildren();get('event-bundle-status').textContent=c.story?'Prepare a combined record from this alert snapshot and the evidence panels currently loaded below.':'Select an alert timeline.';controls();}
  function render(){if(!bundle)return;const d=bundle.document,rows=sortedEventChronology(eventChronology(d),get('event-bundle-basis').value||'collected_at'),included=Object.entries(d.panels).filter(([,p])=>p.state==='included').map(([k])=>k),missing=Object.entries(d.panels).filter(([,p])=>p.state==='not_loaded').map(([k])=>k);
    get('event-bundle-status').textContent=`Prepared ${rows.length} chronology records. Included panels: ${included.join(', ')||'none'}. No loaded result: ${missing.join(', ')||'none'}. Showing ${Math.min(rows.length,200)} rows; exports contain the full bounded chronology and source evidence. Snapshot ${d.story.as_of}.`;
    get('event-bundle-rows').replaceChildren(...rows.slice(0,200).map(r=>{const tr=el('tr');for(const text of [r.collected_at||'Unknown',r.occurred_at||'Unknown',r.title,r.detail+' '+r.time_note])tr.append(el('td',text));return tr;}));controls();
  }
  async function prepare(){refresh();const c=context();if(!c.story||busy)return;const token=++generation;busy=true;bundle=null;controls();get('event-bundle-status').textContent='Checking matching alert snapshots and preparing a portable evidence record…';try{const value=await buildEventBundle({...c,now:clock()});refresh();if(token!==generation)return;bundle=value;render();}catch(e){if(token===generation)get('event-bundle-status').textContent='Combined record unavailable: '+e.message;}finally{if(token===generation){busy=false;controls();}}}
  async function download(html=false){refresh();if(!bundle||busy)return;const current=bundle,token=generation;busy=true;controls();try{const text=html?await eventBundleHTML(current):JSON.stringify(current);refresh();if(token!==generation||current!==bundle)return;const url=window.URL.createObjectURL(new Blob([text],{type:html?'text/html;charset=utf-8':'application/json'})),a=el('a');a.href=url;a.download='ventusiq-event-evidence-'+current.document.story.id.slice(0,12)+(html?'.html':'.json');a.click();window.setTimeout(()=>window.URL.revokeObjectURL(url),1000);}catch(e){if(token===generation)get('event-bundle-status').textContent='Export unavailable: '+e.message;}finally{if(token===generation){busy=false;controls();}}}
  get('event-bundle-prepare').onclick=prepare;get('event-bundle-json').onclick=()=>download(false);get('event-bundle-html').onclick=()=>download(true);get('event-bundle-basis').onchange=render;window.WeatherEventBundle={refresh};refresh();return {refresh,prepare,download,getBundle:()=>bundle};
}
if(typeof window!=='undefined'){const start=()=>mountEventBundle({document,window});if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',start,{once:true});else start();}
